// Curated list of high-quality quant trading blogs.
// Tavily /crawl pricing: ~10 credits per 100 pages basic.
return [
  { json: { url: 'https://quantitativo.com', name: 'Quantitativo' } },
  { json: { url: 'https://robotwealth.com/blog', name: 'Robot Wealth' } },
  { json: { url: 'https://www.quantifiedstrategies.com', name: 'Quantified Strategies' } }
];

const items = $input.all();
const out = [];
for (const item of items) {
  const data = item.json;
  const pages = data.results || data.pages || [];
  const blogName = $('Quant Blogs to Crawl').item.json.name || 'unknown';
  for (const p of pages.slice(0, 10)) {
    const text = (p.raw_content || p.content || '').slice(0, 2000);
    if (text.length < 500) continue;
    out.push({ json: { url: p.url, title: p.title || blogName, content: text, blog: blogName } });
  }
}
console.log(`Yielded ${out.length} candidate articles for scout-ideas`);
return out;

